{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="index.html"><img src="assets/img/avatar.svg" alt="{{COACH_NAME}} avatar" class="logo"> <span class="business">{{BUSINESS_NAME}}</span></a>
      <nav class="nav">
        <ul>
          <li><a href="index.html">Home</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="programs.html">Programs</a></li>
          <li><a href="services.html">Work With Me</a></li>
          <li><a href="pricing.html">Invest</a></li>
          <li><a href="contact.html">Contact</a></li>
        </ul>
      </nav>
      <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <button id="navToggle" class="nav-toggle" aria-label="Open menu">☰</button>
    </div>
  </header>

  <main>
    <section class="hero">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1>Rediscover ease: small rituals, big life shifts</h1>
          <p class="lead">I&#39;m {{COACH_NAME}}, {{CREDENTIALS}}. I guide soulful professionals in {{CITY}}, {{STATE}} to concrete daily practices that restore energy, focus, and joy without overwhelm.</p>
          <p><a class="btn large primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></p>
          <ul class="kicker">
            <li>12-week cohort paths</li>
            <li>Evidence-informed frameworks</li>
            <li>Live group mentoring + micro-habits</li>
          </ul>
        </div>
        <div class="hero-art">
          <img src="assets/img/hero.svg" alt="abstract wellness illustration">
        </div>
      </div>
    </section>

    <section id="diagnostic" class="diagnostic wrap">
      <h2>Quick Clarity Diagnostic</h2>
      <p class="muted">Answer 6 short prompts — get a tailored focus path in seconds.</p>
      <form id="diagnosticForm" class="diag-form">
        <div class="grid cols-2">
          <label>Energy today
            <select name="energy">
              <option value="low">Low</option>
              <option value="moderate">Moderate</option>
              <option value="high">High</option>
            </select>
          </label>
          <label>Stress level
            <select name="stress">
              <option value="low">Low</option>
              <option value="moderate">Moderate</option>
              <option value="high">High</option>
            </select>
          </label>
          <label>Sleep quality
            <select name="sleep">
              <option value="poor">Poor</option>
              <option value="ok">Okay</option>
              <option value="good">Good</option>
            </select>
          </label>
          <label>Movement consistency
            <select name="move">
              <option value="rare">Rare</option>
              <option value="sometimes">Sometimes</option>
              <option value="daily">Daily</option>
            </select>
          </label>
          <label>Time for self
            <select name="self">
              <option value="none">None</option>
              <option value="some">Some</option>
              <option value="regular">Regular</option>
            </select>
          </label>
          <label>Primary goal
            <select name="goal">
              <option value="focus">Focus</option>
              <option value="energy">Energy</option>
              <option value="resilience">Resilience</option>
            </select>
          </label>
        </div>
        <button type="submit" class="btn">Get my focus path</button>
      </form>
      <div id="diagResult" class="diag-result" aria-live="polite"></div>
    </section>

    <section id="plan" class="plan wrap">
      <h2>Signature Framework: The L.I.G.H.T. Path</h2>
      <p class="muted">Learnable steps that stack: Learn, Integrate, Ground, Habit, Thank.</p>
      <div class="grid cols-3">
        <div class="card">
          <h3>Learn</h3>
          <p>Short lessons that synthesize breath, rhythm, and boundary-setting.</p>
        </div>
        <div class="card">
          <h3>Integrate</h3>
          <p>Daily micro-habits we layer into real routines — 5 minutes to start.</p>
        </div>
        <div class="card">
          <h3>Ground</h3>
          <p>Embodied practices to anchor nervous-system balance across the day.</p>
        </div>
        <div class="card">
          <h3>Habit</h3>
          <p>Repetition plans with accountability checkpoints during the cohort.</p>
        </div>
        <div class="card">
          <h3>Thank</h3>
          <p>Reflection rituals for gratitude, tracking wins and momentum.</p>
        </div>
        <div class="card">
          <h3>Cohort Shine</h3>
          <p>Group labs, weekly live Q&amp;A, and a private circle for peer support.</p>
        </div>
      </div>
    </section>

    <section id="micro_habits" class="micro wrap">
      <h2>Micro-habits that move the needle</h2>
      <p class="muted">Pick one to practice for 14 days.</p>
      <ul class="micro-list">
        <li><strong>2-minute morning breath</strong> — immediate anchor to start the day.</li>
        <li><strong>Single-task 25-minute blocks</strong> — protect your energy.</li>
        <li><strong>Evening reset</strong> — 3-minute gratitude + prepare clothes.</li>
        <li><strong>Energy snack</strong> — movement microbreaks every 90 minutes.</li>
      </ul>
      <p class="muted">These are foundational in every cohort and built into your personal plan.</p>
    </section>

    <section id="pricing" class="pricing wrap">
      <h2>Investment & Cohorts</h2>
      <p class="muted">Three pathways depending on how much structure and community you want.</p>
      <div class="pricing-toggle">
        <button class="btn tertiary" data-level="monthly">Monthly</button>
        <button class="btn tertiary active" data-level="cohort">Cohort (recommended)</button>
      </div>
      <div class="grid cols-3 price-cards">
        <div class="price-card" data-price-monthly="79" data-price-cohort="249">
          <h3>Spark</h3>
          <p class="tag">Self-guided</p>
          <p class="price"><span class="amount">$79</span></p>
          <p>Access to lessons, micro-habit trackers, monthly community drop-in.</p>
          <p><a class="btn" href="{{PRIMARY_CTA_URL}}">Join Spark</a></p>
        </div>
        <div class="price-card" data-price-monthly="199" data-price-cohort="699">
          <h3>Flow</h3>
          <p class="tag">Guided small group</p>
          <p class="price"><span class="amount">$199</span></p>
          <p>8-week cohort, live group calls, habit-building curriculum, handouts.</p>
          <p><a class="btn primary" href="{{PRIMARY_CTA_URL}}">Join Flow Cohort</a></p>
        </div>
        <div class="price-card" data-price-monthly="499" data-price-cohort="1399">
          <h3>Tribe</h3>
          <p class="tag">Deep support</p>
          <p class="price"><span class="amount">$499</span></p>
          <p>12-week cohort, small group, 1:1 consult, long-term relapse plan, lifetime materials.</p>
          <p><a class="btn primary" href="{{PRIMARY_CTA_URL}}">Apply to Tribe</a></p>
        </div>
      </div>
      <p class="muted">Cohort pricing reflects the full program commitment and group mentoring model.</p>
    </section>

    <section class="cta wrap">
      <h2>Ready to begin?</h2>
      <p>Reserve a spot in the next cohort — seats are limited.</p>
      <p><a class="btn large primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></p>
      <p class="muted">Prefer a quick chat? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-grid">
        <div>
          <p class="brandline">{{BUSINESS_NAME}} — {{TAGLINE}}</p>
          <p>{{COACH_NAME}}, {{CREDENTIALS}} • {{CITY}}, {{STATE}}</p>
        </div>
        <nav class="foot-nav">
          <ul>
            <li><a href="about.html">About</a></li>
            <li><a href="programs.html">Programs</a></li>
            <li><a href="testimonials.html">Praise</a></li>
            <li><a href="book.html">Book</a></li>
            <li><a href="contact.html">Contact</a></li>
          </ul>
        </nav>
        <div class="contact">
          <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
          <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
      </div>
      <p class="copyright">© <span id="year"></span> {{BUSINESS_NAME}}</p>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
