{"path":"assets/css/styles.css","content":":root{
  --accent:#FF6B6B;
  --accent-2:#4ECDC4;
  --bg:#111214;
  --card:#0F1720;
  --muted:#9AA3AA;
  --text:#E6EFF1;
  --radius:12px;
  --gap:18px;
  --max:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial;color:var(--text);background:linear-gradient(180deg,#071018 0%, #09131A 100%);-webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.site-header{background:linear-gradient(90deg, rgba(255,255,255,0.03), transparent);backdrop-filter:blur(6px);position:sticky;top:0;z-index:10}
.site-header .wrap{display:flex;align-items:center;gap:12px}
.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--text)}
.logo{width:48px;height:48px}
.nav{margin-left:auto}
.nav ul{display:flex;gap:12px;list-style:none;margin:0;padding:0}
.nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a:hover{color:var(--text);background:rgba(255,255,255,0.02)}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;background:transparent;color:var(--text);border:1px solid rgba(255,255,255,0.06);text-decoration:none}
.btn:hover{transform:translateY(-2px)}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#08201F;border:none}
.btn.large{padding:14px 20px;border-radius:14px;font-weight:600}
.btn.tertiary{background:transparent;border:1px dashed rgba(255,255,255,0.04)}
.hero{padding:36px 0}
.hero-grid{display:grid;grid-template-columns:1fr 380px;align-items:center;gap:28px}
.hero-copy h1{font-size:clamp(28px,4vw,44px);margin:0 0 12px;color:var(--text)}
.lead{color:var(--muted);margin:0 0 16px;line-height:1.5}
.kicker{display:flex;gap:10px;padding:0;margin:12px 0 0;list-style:none}
.kicker li{background:rgba(255,255,255,0.03);padding:6px 8px;border-radius:8px;font-size:13px;color:var(--muted)}
.hero-art img{width:100%;height:auto;display:block}
.diagnostic{margin-top:26px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:22px;border-radius:12px}
.diag-form .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
.diag-form label{display:block;font-size:14px;color:var(--muted)}
.diag-form select{width:100%;padding:8px;margin-top:6px;border-radius:8px;background:rgba(0,0,0,0.3);border:1px solid rgba(255,255,255,0.03);color:var(--text)}
.diag-result{margin-top:12px;padding:12px;border-radius:10px;background:rgba(0,0,0,0.25);color:var(--accent-2)}
.plan{margin-top:26px}
.grid{display:grid;gap:14px}
.cols-2{grid-template-columns:repeat(2,1fr)}
.cols-3{grid-template-columns:repeat(3,1fr)}
.card{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
.micro{margin-top:20px}
.micro-list{list-style:none;padding:0;margin:12px 0 0}
.micro-list li{padding:10px 12px;border-radius:10px;background:rgba(255,255,255,0.015);margin-bottom:10px}
.pricing{margin-top:20px}
.pricing-toggle{display:flex;gap:8px;margin-bottom:12px}
.price-cards .price-card{background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
.price-card .tag{font-size:12px;color:var(--muted)}
.price-card .price{font-size:22px;margin:8px 0}
.price-card .amount{font-weight:700;color:var(--accent-2)}
.cta{margin:32px 0;padding:22px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);text-align:center}
.site-footer{border-top:1px solid rgba(255,255,255,0.03);padding:22px 0;margin-top:40px}
.foot-grid{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}
.brandline{font-weight:700}
.muted{color:var(--muted)}
@media (max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .nav ul{display:none}
  .nav-toggle{display:inline-block}
  .foot-grid{flex-direction:column}
  .cols-3{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // small UI behaviors for the cohort site
  var navToggle = document.getElementById('navToggle');
  navToggle && navToggle.addEventListener('click', function(){
    var nav = document.querySelector('.nav ul');
    if(!nav) return;
    nav.style.display = nav.style.display === 'flex' ? 'none' : 'flex';
  });

  // diagnostic form simple matcher
  var form = document.getElementById('diagnosticForm');
  var result = document.getElementById('diagResult');
  form && form.addEventListener('submit', function(e){
    e.preventDefault();
    var data = new FormData(form);
    var score = 0;
    var map = {low:0,rare:0,none:0,poor:0,moderate:1,sometimes:1,ok:1,high:2,daily:2,regular:2,good:2};
    for(var pair of data.entries()){ score += (map[pair[1]]||0); }
    var path = '';
    if(score <= 4) path = 'Rest & Rebuild: focus on gentle rhythms and sleep hygiene.';
    else if(score <= 8) path = 'Stability Path: anchor micro-habits and weekly rhythm.';
    else path = 'Momentum Path: deepen routines and community accountability.';
    result.textContent = path + ' Recommended program: ' + (score<=4? 'Spark' : (score<=8? 'Flow' : 'Tribe')) + '.';
  });

  // pricing toggle
  var toggles = document.querySelectorAll('.pricing-toggle .btn');
  toggles.forEach(function(btn){
    btn.addEventListener('click', function(){
      toggles.forEach(function(b){b.classList.remove('active')});
      btn.classList.add('active');
      var level = btn.getAttribute('data-level');
      document.querySelectorAll('.price-card').forEach(function(card){
        var m = card.getAttribute('data-price-monthly');
        var c = card.getAttribute('data-price-cohort');
        var amount = level === 'monthly' ? m : c;
        card.querySelector('.amount').textContent = '$' + amount;
      });
    });
  });

  // set year
  var y = document.getElementById('year');
  if(y) y.textContent = new Date().getFullYear();
})();"} 
